package com.ykt.assistant;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
public class AiProtocolTest {
    LessonQuiz quiz;LessonQuiz.Question q;AiQuestion snapshot;
    void question(int type)throws Exception{quiz=new LessonQuiz("private-lesson",()->1800000000000L,()->1000L);JSONObject spec=RainApi.object("problemId","private-question","problemType",type,"body","<p>题干 &amp; 条件</p>","options",new JSONArray("[{\"key\":\"A\",\"value\":\"第一项\"},{\"key\":\"C\",\"value\":\"第二项\"}]"),"pollingCount",1,"blanks",new JSONArray("[{\"num\":2},{\"num\":1}]"),"answers",new JSONArray().put("HIDDEN"),"remark","HIDDEN");quiz.deck("private-presentation",RainApi.object("slides",new JSONArray().put(RainApi.object("problem",spec))));quiz.ingest(RainApi.object("op","unlockproblem","problem",RainApi.object("prob","private-question","dt",1800000000000L,"limit",60)));q=quiz.get("private-question");snapshot=new AiQuestion(q);}
    JSONObject response(String state,JSONArray options,JSONArray blanks,String text)throws Exception{return RainApi.object("schema_version",1,"question_token",snapshot.token,"problem_type",q.type(),"status",state,"answer",RainApi.object("option_keys",options,"blank_values",blanks,"text",text),"explanation","示例步骤与理由","confidence",.8);}
    JSONObject choice(String key)throws Exception{return response("answered",new JSONArray().put(key),new JSONArray(),"");}
    void invalid(JSONObject value)throws Exception{try{snapshot.parse(value.toString());fail();}catch(Exception expected){assertTrue(expected.getMessage().contains("JSON"));}}
    @Test public void endpointAcceptsBaseAndFullUrlWithoutDuplicateSuffix(){assertEquals("https://example.com/v1/chat/completions",new AiConfig("https://example.com/v1/","m","",false,false,false).endpoint.toString());assertEquals("https://example.com/v1/chat/completions",new AiConfig("https://example.com","m","",false,false,false).endpoint.toString());assertEquals("https://example.com/custom/chat/completions",new AiConfig("https://example.com/custom/chat/completions","m","key",true,false,false).endpoint.toString());}
    @Test public void invalidEndpointAndHeaderInjectionAreRejected(){for(String url:new String[]{"http://example.com/v1","https://user:pass@example.com","https://example.com/?key=secret","https://example.com/#a","invalid"})try{new AiConfig(url,"m","",false,false,false);fail(url);}catch(IllegalArgumentException expected){}for(String key:new String[]{"bad\nkey","bad key","中文"})try{new AiConfig("https://example.com","m",key,false,false,false);fail();}catch(IllegalArgumentException expected){}}
    @Test public void outboundQuestionContainsNoIdsAnswersOrDrafts()throws Exception{question(1);q.selected.add("A");AiQuestion copy=new AiQuestion(q);String payload=copy.payload.toString();assertFalse(payload.contains("private-"));assertFalse(payload.contains("HIDDEN"));assertFalse(payload.contains("selected"));assertEquals("题干 & 条件",copy.payload.getString("body"));assertTrue(AiQuestion.SYSTEM_PROMPT.contains("标准 JSON"));}
    @Test public void singleChoiceFillsKeysWithoutSubmitting()throws Exception{question(1);AiQuestion.Result result=snapshot.parse(choice("C").toString());snapshot.apply(quiz,q,result);assertEquals(java.util.Collections.singleton("C"),q.selected);assertFalse(q.submitted);assertFalse(q.sending);assertEquals("[\"C\"]",quiz.prepare(q).payload().getJSONArray("result").toString());}
    @Test public void multipleChoiceAndVoteLimitsAreValidated()throws Exception{question(2);JSONObject value=response("answered",new JSONArray().put("A").put("C"),new JSONArray(),"");assertEquals(2,snapshot.parse(value.toString()).options.size());question(3);invalid(response("answered",new JSONArray().put("A").put("C"),new JSONArray(),""));}
    @Test public void blankAndTextAnswersUseSeparateFields()throws Exception{question(4);AiQuestion.Result r=snapshot.parse(response("answered",new JSONArray(),new JSONArray().put("first").put("second"),"").toString());snapshot.apply(quiz,q,r);assertEquals(java.util.Arrays.asList("first","second"),q.fields);question(5);r=snapshot.parse(response("answered",new JSONArray(),new JSONArray(),"文字推导").toString());snapshot.apply(quiz,q,r);assertEquals("文字推导",q.text);}
    @Test public void unknownKeysDuplicatesWrongTypesAndWrongTokenAreRejected()throws Exception{question(1);invalid(choice("B"));invalid(response("answered",new JSONArray().put("A").put("A"),new JSONArray(),""));invalid(choice("A").put("question_token","other"));invalid(choice("A").put("problem_type",2));invalid(choice("A").put("schema_version","1"));invalid(choice("A").put("confidence",2));}
    @Test public void uncertaintyCannotFillEvenWithValidEnvelope()throws Exception{question(1);AiQuestion.Result result=snapshot.parse(response("uncertain",new JSONArray(),new JSONArray(),"").toString());assertFalse(result.answered());try{snapshot.apply(quiz,q,result);fail();}catch(Exception expected){}assertTrue(q.selected.isEmpty());invalid(response("uncertain",new JSONArray().put("A"),new JSONArray(),""));}
    @Test public void narrowJsonFenceAcceptedButProseAndTruncatedJsonRejected()throws Exception{question(1);String json=choice("A").toString();assertTrue(snapshot.parse("```json\n"+json+"\n```").answered());for(String text:new String[]{"answer: "+json,json+" trailing",json.substring(0,json.length()-1)})try{snapshot.parse(text);fail();}catch(Exception expected){}}
    @Test public void changedRoundOrContentAndSubmittedQuestionRejectStaleFill()throws Exception{question(1);AiQuestion.Result result=snapshot.parse(choice("A").toString());q.round++;assertFalse(snapshot.matches(quiz,q));try{snapshot.apply(quiz,q,result);fail();}catch(Exception expected){}q.round--;q.spec.put("body","changed");assertFalse(snapshot.matches(quiz,q));question(1);q.submitted=true;assertFalse(snapshot.matches(quiz,q));}
    @Test public void judgmentAiUsesOnlyOneOriginalOptionKey()throws Exception {
        question(6);assertEquals(1,snapshot.payload.getInt("max_selections"));AiQuestion.Result result=snapshot.parse(choice("C").toString());snapshot.apply(quiz,q,result);assertTrue(q.selected.contains("C"));
    }
}
